      @Schema(name = "channel")
      Build.Channel channel,
      @Schema(name = "promoted")
      boolean promoted,
      @Schema(name = "changes")
      List<Build.Change> changes,
      @Schema(name = "downloads")
      Map<String, Build.Download> downloads
    ) {
    }
  }
}

